const j = $input.first().json;
const b = j.body && typeof j.body === 'object' ? j.body : null;
return [{ json: {
  phone: String(b ? b.From || '' : j.phone || '').trim(),
  text: String(b ? b.Body || '' : j.text || '').trim(),
  via: b ? 'twilio' : 'dashboard'
} }];

const msg = $('Text Details').first().json;
const s = $('Load Settings').first().json;
const NL = String.fromCharCode(10);
const tz = s.timezone || 'America/Chicago';
const now = DateTime.now().setZone(tz);
const nowIso = now.toUTC().toISO();
const stamp = now.toMillis().toString(36);
const makeId = p => p + stamp + Math.floor(Math.random() * 46656).toString(36);
const clean = r => {
  const o = Object.assign({}, r);
  delete o.id;
  delete o.createdAt;
  delete o.updatedAt;
  return o;
};
const ms = v => (v ? new Date(v).getTime() : 0);

let services = [];
try {
  services = typeof s.services === 'string' ? JSON.parse(s.services) : s.services || [];
} catch (e) {
  services = [];
}
if (!Array.isArray(services) || !services.length) {
  services = [
    { key: 'leak', name: 'Burst or leaking pipe', from: 149, typical: 480, urgent: true },
    { key: 'drain', name: 'Blocked drain', from: 129, typical: 260 },
    { key: 'heater', name: 'Water heater repair', from: 189, typical: 690 },
    { key: 'heating', name: 'No heat or furnace repair', from: 159, typical: 380 },
    { key: 'toilet', name: 'Toilet repair', from: 99, typical: 190 },
    { key: 'faucet', name: 'Faucet or sink repair', from: 99, typical: 170 },
    { key: 'install', name: 'New fixture install', from: 0, typical: 650 },
    { key: 'gas', name: 'Gas leak', from: 0, typical: 350, urgent: true },
    { key: 'other', name: 'General plumbing', from: 119, typical: 240 }
  ];
}

const phone = String(msg.phone || '').trim();
const text = String(msg.text || '').trim().slice(0, 600);
const mine = $('Find Texter').all().map(i => i.json).filter(r => r && r.lead_id && r.phone === phone);
mine.sort((a, b) => ms(b.created_at) - ms(a.created_at));
let lead = mine[0] && now.toMillis() - ms(mine[0].last_at) < 14 * 86400000 ? clean(mine[0]) : null;
if (!lead) {
  lead = {
    lead_id: makeId('l'), phone, name: null, status: 'chatting', source: 'sms', service: null, issue: null, urgency: null,
    urgent: false, zip: null, address: null, offered: '[]', slot: null, value: 0, needs_call: false, ack: true, ai_paused: false,
    follow_ups: 0, text_back_seconds: null, first_reply_at: null, alerted_at: null, booked_at: null, booked_by: null,
    reason: null, summary: null, created_at: nowIso, last_at: nowIso, call_count: 0
  };
}

const history = $('Load Thread').all().map(i => i.json).filter(r => r && r.lead_id === lead.lead_id);
history.sort((a, b) => ms(a.at) - ms(b.at));
const inbound = { msg_id: makeId('m'), lead_id: lead.lead_id, phone, dir: 'in', author: 'customer', body: text, at: nowIso };
lead.last_at = nowIso;
if (!lead.first_reply_at) lead.first_reply_at = nowIso;

const word = text.toLowerCase().split('.').join('').split('!').join('').trim();
let mode = 'ai';
let fixed = [];
if (['stop', 'stopall', 'unsubscribe', 'cancel', 'end', 'quit'].includes(word)) {
  lead.status = 'opted_out';
  mode = 'fixed';
  fixed = ["You're unsubscribed and won't get more texts from us. Reply START if you change your mind."];
} else if (lead.status === 'opted_out') {
  if (['start', 'unstop', 'yes'].includes(word)) {
    lead.status = 'chatting';
    mode = 'fixed';
    fixed = ["You're back in. What can we help with?"];
  } else {
    mode = 'silent';
  }
} else if (!s.aiEnabled || lead.ai_paused) {
  mode = 'owner';
  lead.needs_call = true;
  lead.ack = false;
  if (lead.status === 'texted' || lead.status === 'no_reply') lead.status = 'chatting';
} else if (lead.status === 'texted' || lead.status === 'no_reply') {
  lead.status = 'chatting';
}

const toMin = v => {
  const p = String(v).trim().split(':');
  return Number(p[0]) * 60 + Number(p[1] || 0);
};
const taken = {};
$('Load Booked Jobs').all().map(i => i.json).forEach(r => {
  if (!r || !r.slot || r.urgent || r.lead_id === lead.lead_id || r.status !== 'booked') return;
  const k = ms(r.slot);
  taken[k] = (taken[k] || 0) + 1;
});
const times = String(s.slotTimes || '').split(',').map(x => x.trim()).filter(Boolean).map(toMin).sort((a, b) => a - b);
const cap = Math.max(1, Number(s.vans) || 1);
const slots = [];
for (let i = 0; i < 14 && slots.length < 12; i++) {
  const day = now.startOf('day').plus({ days: i });
  if (day.weekday === 7) continue;
  const range = String(day.weekday === 6 ? s.saturdayHours : s.weekdayHours).split('-');
  if (range.length < 2) continue;
  const open = toMin(range[0]);
  const close = toMin(range[1]);
  for (const m of times) {
    if (m < open || m + 60 > close) continue;
    const t = day.plus({ minutes: m });
    if (t.toMillis() < now.toMillis() + 90 * 60000) continue;
    if ((taken[t.toMillis()] || 0) >= cap) continue;
    const rel = i === 0 ? 'today' : i === 1 ? 'tomorrow' : t.toFormat('cccc');
    slots.push({ id: 'S' + (slots.length + 1), iso: t.toUTC().toISO(), label: rel + ' (' + t.toFormat('ccc LLL d') + ') at ' + t.toFormat('h:mm a') });
    if (slots.length >= 12) break;
  }
}

let offered = [];
try {
  offered = JSON.parse(lead.offered || '[]');
} catch (e) {
  offered = [];
}
const offeredIds = slots.filter(x => offered.includes(x.iso)).map(x => x.id);
const known = {
  name: lead.name, service: lead.service, issue: lead.issue, urgency: lead.urgency, zip: lead.zip, address: lead.address,
  status: lead.status, emergency_already_flagged: !!lead.urgent, slots_already_offered: offeredIds,
  booked_for: lead.status === 'booked' && lead.slot ? DateTime.fromMillis(ms(lead.slot)).setZone(tz).toFormat('cccc LLL d, h:mm a') : null
};

const svcLines = services.map(v => '- ' + v.key + ': ' + v.name + (v.from ? ', visits from ' + (s.currency || '$') + v.from : ', free quote') + (v.urgent ? ', always an emergency' : '')).join(NL);
const system = [
  'You are the text assistant for ' + s.businessName + ', a plumbing and heating company serving ' + s.areaLabel + '. ' + s.ownerName + ' is the owner.',
  'A customer called, nobody could pick up, and the business texted them back automatically. You now carry on the conversation by SMS on behalf of the business.',
  '',
  'Your job, in order: find out what the problem is and how urgent it is, get the ZIP code of the job, offer open times, get the name for the booking, then confirm the booking.',
  '',
  'How to write:',
  '- Sound like a friendly person at a local trade business. Plain words, short sentences, no emojis.',
  '- Keep each text under 300 characters. Send one text, or two only when giving safety advice.',
  '- Ask one question at a time.',
  '- Only quote prices from the service list, and say the price is confirmed before work starts.',
  '- Only offer times from the open slots list, at most three at once. Never invent a time.',
  '- Never promise anything else on behalf of the business.',
  '',
  'Emergencies (burst pipe, flooding, water through a ceiling, sewage backing up, a gas smell): say ' + s.ownerName + ' has been alerted and will call within 10 minutes, give one safety step (turn off the main water valve; for gas, leave the house and call 911 or the gas company from outside), and ask for the address. Once you have the address or ZIP, use action dispatch and say ' + s.ownerName + ' is on the way.',
  'If they ask for a call or a real person, say ' + s.ownerName + ' will call back soon and use action call_back.',
  'If they have sorted it or gone elsewhere, close politely and use action lost.',
  'If their ZIP code is outside the area, say so kindly and use action out_of_area.',
  '',
  'Reply with JSON only, no other text, in this shape:',
  '{"replies": ["text"], "lead": {"name": null, "service": null, "issue": null, "urgency": null, "zip": null, "address": null, "summary": null}, "offer_slot_ids": [], "book_slot_id": null, "action": "none"}',
  'service is one of the service keys. urgency is emergency, soon or routine. action is none, offer, book, dispatch, call_back, lost or out_of_area.',
  'Use action offer with offer_slot_ids when you offer times. Use action book with book_slot_id only when the customer has picked a time and you know their name. Keep fields you already know.'
].join(NL);

const transcript = history.concat([inbound]).filter(m => m.dir !== 'note').slice(-30)
  .map(m => (m.dir === 'in' ? 'Customer' : m.author === 'owner' ? s.ownerName : 'Business') + ': ' + m.body).join(NL);
const user = [
  'Services:', svcLines, '',
  'Opening hours: Monday to Friday ' + s.weekdayHours + ', Saturday ' + s.saturdayHours + '. Emergencies any time.',
  'ZIP codes we cover (prefixes): ' + s.serviceZips,
  'Right now it is ' + now.toFormat('cccc LLL d, h:mm a') + '.', '',
  'Open slots:', slots.length ? slots.map(x => x.id + ': ' + x.label).join(NL) : 'None in the next two weeks. Offer a call back instead.', '',
  'What we know so far: ' + JSON.stringify(known), '',
  'Conversation so far:', transcript, '',
  'Write the next reply as JSON.'
].join(NL);

return [{ json: {
  mode, fixed, lead, inbound, slots, services, phone,
  system_prompt: system, user_prompt: user,
  model: s.claudeModel || 'claude-opus-5',
  demo: !!s.demoMode, owner_name: s.ownerName, owner_phone: s.ownerPhone, business_phone: s.businessPhone
} }];

const p = $('Prepare Conversation').first().json;
const lead = Object.assign({}, p.lead);
const nowMs = Date.now();
const iso = t => new Date(t).toISOString();
const stamp = nowMs.toString(36);
const makeId = x => x + stamp + Math.floor(Math.random() * 46656).toString(36);
const who = lead.name || lead.phone;
const svcOf = key => p.services.find(v => v.key === key) || p.services.find(v => v.key === 'other') || { typical: 240, name: 'General plumbing' };
const rows = [p.inbound];
const notes = [];
let replies = [];
let alert = null;

if (p.mode === 'fixed') replies = p.fixed;
if (p.mode === 'owner') alert = 'New text from ' + who + ': ' + p.inbound.body;

if (p.mode === 'ai') {
  const r = $input.first() ? $input.first().json : {};
  let raw = '';
  if (typeof r.merged_response === 'string') raw = r.merged_response;
  else if (Array.isArray(r.content)) raw = r.content.filter(c => c && c.type === 'text').map(c => c.text).join('');
  else if (typeof r.content === 'string') raw = r.content;
  else if (typeof r.text === 'string') raw = r.text;
  let parsed = null;
  try {
    parsed = JSON.parse(raw.slice(raw.indexOf('{'), raw.lastIndexOf('}') + 1));
  } catch (e) {
    parsed = null;
  }
  if (!parsed || !Array.isArray(parsed.replies)) {
    replies = ['Thanks, got it. ' + p.owner_name + ' will get back to you shortly.'];
    lead.needs_call = true;
    lead.ack = false;
    alert = 'The AI could not answer ' + who + '. Please text them back.';
  } else {
    const f = parsed.lead || {};
    ['name', 'issue', 'zip', 'address', 'summary'].forEach(k => {
      if (f[k]) lead[k] = String(f[k]).slice(0, 140);
    });
    if (f.service && p.services.some(v => v.key === f.service)) lead.service = f.service;
    if (['emergency', 'soon', 'routine'].includes(f.urgency)) lead.urgency = f.urgency;
    if (lead.service && !lead.issue) lead.issue = svcOf(lead.service).name;
    const svc = svcOf(lead.service);
    const emergency = lead.urgency === 'emergency' || (lead.service && svc.urgent);
    if (emergency && !lead.urgent) {
      lead.urgent = true;
      lead.ack = false;
      alert = 'Emergency: ' + (lead.issue || 'urgent job') + ' for ' + (lead.name ? lead.name + ' on ' + lead.phone : lead.phone);
    }
    if (emergency && lead.status !== 'booked') lead.status = 'urgent';
    const byId = id => p.slots.find(x => x.id === id);
    const act = String(parsed.action || 'none');
    if (act === 'offer') {
      const picked = (parsed.offer_slot_ids || []).map(byId).filter(Boolean).map(x => x.iso);
      if (picked.length) lead.offered = JSON.stringify(picked);
    }
    if (act === 'book') {
      const sl = byId(parsed.book_slot_id);
      if (sl && lead.name) {
        lead.slot = sl.iso;
        lead.status = 'booked';
        lead.booked_at = iso(nowMs);
        lead.booked_by = 'ai';
        lead.value = Number(svc.typical) || 0;
        lead.needs_call = false;
        notes.push('Booked by AI: ' + (lead.issue || svc.name) + ', ' + sl.label);
      }
    }
    if (act === 'dispatch') {
      lead.status = 'booked';
      lead.urgent = true;
      lead.slot = iso(nowMs + 45 * 60000);
      lead.booked_at = iso(nowMs);
      lead.booked_by = 'ai';
      lead.value = Number(svc.typical) || 0;
      notes.push('Emergency visit on the way');
      alert = 'Head to ' + (lead.address || lead.zip || 'the customer') + ' for ' + who + ': ' + (lead.issue || 'emergency') + '. Their number is ' + lead.phone + '.';
    }
    if (act === 'call_back') {
      lead.needs_call = true;
      lead.ack = false;
      alert = who + ' asked for a call back' + (lead.issue ? ' about ' + String(lead.issue).toLowerCase() : '') + '. Number: ' + lead.phone;
    }
    if (act === 'lost' || act === 'out_of_area') {
      lead.status = 'lost';
      lead.reason = act === 'lost' ? 'Went elsewhere or fixed it' : 'Outside the service area';
      lead.slot = null;
    }
    replies = parsed.replies.map(x => String(x || '').trim()).filter(Boolean).slice(0, 2).map(x => x.slice(0, 320));
  }
}

let t = nowMs + 500;
replies.forEach(body => {
  rows.push({ msg_id: makeId('m'), lead_id: lead.lead_id, phone: lead.phone, dir: 'out', author: 'ai', body, at: iso(t) });
  t += 1000;
});
if (alert) {
  lead.alerted_at = lead.alerted_at || iso(t);
  rows.push({ msg_id: makeId('n'), lead_id: lead.lead_id, phone: lead.phone, dir: 'note', author: 'system', body: p.owner_name + ' alerted by text: ' + alert, at: iso(t) });
  t += 500;
}
notes.forEach(body => {
  rows.push({ msg_id: makeId('n'), lead_id: lead.lead_id, phone: lead.phone, dir: 'note', author: 'system', body, at: iso(t) });
  t += 500;
});
if (replies.length) lead.last_at = iso(t);

return [{ json: {
  lead, messages: rows, replies, alert,
  send: !p.demo, phone: lead.phone, from: p.business_phone, owner_phone: p.owner_phone
} }];
